using System;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
class BridgeStateTests {
static Type P;static object Call(string op,Dictionary<string,object> r){r["operation"]=op;return P.GetMethod("Dispatch",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{r});}static Dictionary<string,object> R(params object[] p){var d=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)d[(string)p[i]]=p[i+1];return d;}static void Assert(bool ok,string m){if(!ok)throw new Exception(m);}
[STAThread]static void Main(string[] a){P=Assembly.LoadFrom(a[2]).GetType("Program",true);string sid=null;try{var attached=(Dictionary<string,object>)Call("attach",R("processId",int.Parse(a[0]),"expectedStartTimeUtc",a[1]));sid=(string)attached["sessionId"];var sessions=(IDictionary)P.GetField("Sessions",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);var session=sessions[sid];var st=session.GetType();var jobType=P.GetNestedType("BuildJob",BindingFlags.NonPublic);object last=null;string first=null;for(int i=0;i<70;i++){var job=Activator.CreateInstance(jobType,true);string id=Guid.NewGuid().ToString();if(i==0)first=id;foreach(var pair in R("Id",id,"Action","build","Phase","build","State","succeeded","StartedUtc",DateTime.UtcNow.ToString("o")))jobType.GetField(pair.Key).SetValue(job,pair.Value);jobType.GetField("Complete").SetValue(job,true);st.GetMethod("TrackBuild").Invoke(session,new object[]{job});last=job;}var builds=(IDictionary)st.GetField("Builds").GetValue(session);Assert(builds.Count==64,"Build history not bounded");Assert(!builds.Contains(first),"Old build retained");jobType.GetField("State").SetValue(last,"started");jobType.GetField("Complete").SetValue(last,false);jobType.GetField("LastBuildInfo").SetValue(last,3);st.GetField("ActiveBuild").SetValue(session,last);var result=(Dictionary<string,object>)Call("buildReconcile",R("sessionId",sid,"buildId",jobType.GetField("Id").GetValue(last)));Assert((bool)result["reconciled"],"Did not reconcile");Assert((string)result["state"]=="unconfirmed"&&!(bool)result["complete"]&&result["lastBuildInfo"]==null,"Reconciliation invented outcome");Assert(st.GetField("ActiveBuild").GetValue(session)==null,"Active build stayed locked");Console.WriteLine(new JavaScriptSerializer().Serialize(R("passed",true,"builds",builds.Count,"evicted",st.GetField("EvictedBuilds").GetValue(session),"reconciled",result)));}finally{if(sid!=null)Call("detach",R("sessionId",sid));}}}

